/* Every make/model pair, flattened once for searching. */
const VPIC_FLAT = Object.entries(VPIC_MODELS).flatMap(([mk, models]) =>
  Object.entries(models).map(([md, yrs]) => ({ mk, md, y0: yrs[0], y1: yrs[1] })));

/* Models this make is known to have built, for the add-vehicle datalist. */
function vpicModelsFor(make) {
  return Object.keys(VPIC_MODELS[make] || {});
}

/* Free-text search across the index. Used when a lookup comes back empty. */
function vpicSearch(q, limit) {
  const s = String(q || '').trim().toLowerCase();
  if (s.length < 2) return [];
  const hits = VPIC_FLAT.filter(r =>
    r.md.toLowerCase().includes(s) || (r.mk + ' ' + r.md).toLowerCase().includes(s));
  /* Prefer a match at the start of the model name, then longer production runs. */
  hits.sort((a, b) => {
    const as = a.md.toLowerCase().startsWith(s) ? 0 : 1;
    const bs = b.md.toLowerCase().startsWith(s) ? 0 : 1;
    return as - bs || (b.y1 - b.y0) - (a.y1 - a.y0) || a.mk.localeCompare(b.mk);
  });
  return hits.slice(0, limit || 6);
}
